#include <bits/stdc++.h>
using namespace std;const long long P=1000003;
long long pw(long long x,int e){long long y=1;for(;e;e>>=1,x=x*x%P)if(e&1)y=y*x%P;return y;}
long long binom(int n,int k){if(k<0||k>n)return 0;long long x=1;for(int i=1;i<=k;i++)x=x*(n+1-i)/i;return x;}
int rankm(vector<vector<long long>>a,int c){int r=0;for(int j=0;j<c&&r<(int)a.size();j++){int k=r;while(k<(int)a.size()&&!a[k][j])k++;if(k==(int)a.size())continue;swap(a[k],a[r]);auto inv=pw(a[r][j],P-2);for(int t=j;t<c;t++)a[r][t]=a[r][t]*inv%P;for(k=r+1;k<(int)a.size();k++)if(a[k][j]){auto m=a[k][j];for(int t=j;t<c;t++)a[k][t]=(a[k][t]-m*a[r][t]%P+P)%P;}r++;}return r;}
int main(int argc,char**argv){int deg=23,m=4;vector<pair<int,int>>pts,b;for(int r=3;r<=8;r++)for(int s=0;s<=r/2;s++)pts.push_back({r,s*(r-s)});for(int c=0;2*c<=deg;c++)for(int a=0;a+2*c<=deg;a++)b.push_back({a,c});vector<vector<vector<long long>>>J;for(auto[r,v]:pts){bool diag=4*v==r*r;vector<vector<long long>> rows;for(int i=0;i<m;i++)for(int h=0;i+h<m;h++){if(diag&&i+2*h>=m)continue;vector<long long>row;for(auto[a,c]:b){long long x=0;if(!diag){if(a>=i&&c>=h)x=binom(a,i)%P*binom(c,h)%P*pw(r,a-i)%P*pw(v,c-h)%P;}else{int s=r/2;for(int k=0;k<=i;k++)if(k<=a&&i-k<=c-h&&h<=c)x=(x+binom(a,k)%P*binom(c,h)%P*binom(c-h,i-k)%P*pw(r,a-k)%P*pw(v,c-h-i+k)%P*pw(s,i-k))%P;}row.push_back(x);}rows.push_back(row);}J.push_back(rows);}ifstream in(argv[1]);int mask,ra,r0;map<int,int>ct;while(in>>mask>>ra>>r0){vector<vector<long long>>A;for(int i=0;i<21;i++)if(mask>>i&1)for(auto&row:J[i])A.push_back(row);int rank=rankm(A,b.size());ct[rank]++;cout<<mask<<" "<<A.size()<<" "<<rank<<"\n";}for(auto[k,v]:ct)cerr<<k<<":"<<v<<"\n";}
